  let sound=false,audio=null,ambientNodes=[];
  function initAudio(){if(audio)return;try{audio=new (window.AudioContext||window.webkitAudioContext)();}catch(e){return;}const buffer=audio.createBuffer(1,audio.sampleRate*3,audio.sampleRate);const data=buffer.getChannelData(0);let value=0;for(let i=0;i<data.length;i++){value=(value+(Math.random()*2-1)*.018)/1.018;data[i]=value*3;}const noise=audio.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=250;const gain=audio.createGain();gain.gain.value=0;noise.connect(filter);filter.connect(gain);gain.connect(audio.destination);noise.start();ambientNodes=[gain];}
  function setAudioActive(on){if(!audio)return;if(on&&sound)audio.resume?.().catch(()=>{});else if(!on)audio.suspend?.().catch(()=>{});}
  function updateSound(){ $('sound-toggle').innerHTML='♪ <span>SOUND '+(sound?'ON':'OFF')+'</span>';$('sound-toggle').setAttribute('aria-label',sound?'サウンドを無効にする':'サウンドを有効にする');$('sound-toggle').setAttribute('aria-pressed',String(sound));if(sound){initAudio();audio?.resume?.().catch(()=>{});}if(ambientNodes[0])ambientNodes[0].gain.setTargetAtTime(sound?.18:0,audio.currentTime,.2);}
  const noiseCache={};function noiseBuffer(key,duration,fill){if(!noiseCache[key]){const b=audio.createBuffer(1,Math.floor(audio.sampleRate*duration),audio.sampleRate);fill(b.getChannelData(0));noiseCache[key]=b;}return noiseCache[key];}
  function sfx(type){if(!sound||!audio)return;const now=audio.currentTime;const gain=audio.createGain();gain.connect(audio.destination);if(type==='explosion'||type==='thunder'){const duration=type==='thunder'?1.8:.8,b=noiseBuffer(type,duration,data=>{let previous=0;for(let i=0;i<data.length;i++){previous=previous*.85+(Math.random()*2-1)*.15;data[i]=previous*Math.pow(1-i/data.length,1.6);}});const src=audio.createBufferSource();src.buffer=b;gain.gain.value=type==='thunder'?.27:.5;src.connect(gain);src.start();src.onended=()=>{src.disconnect();gain.disconnect();};return;}if(type==='shoot'||type==='hit'){const duration=type==='shoot'?.15:.09;const b=noiseBuffer(type,duration,a=>{for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/a.length,2);});const src=audio.createBufferSource();src.buffer=b;const f=audio.createBiquadFilter();f.type='lowpass';f.frequency.value=type==='shoot'?(state.weapon===2?900:2200):450;src.connect(f);f.connect(gain);gain.gain.setValueAtTime(type==='shoot'?.45:.25,now);src.start();src.onended=()=>{src.disconnect();f.disconnect();gain.disconnect();};}else{const osc=audio.createOscillator();osc.type=type==='buy'?'sine':'triangle';osc.frequency.setValueAtTime(type==='buy'?520:type==='reload'?220:130,now);osc.frequency.exponentialRampToValueAtTime(type==='buy'?1000:70,now+.13);gain.gain.setValueAtTime(.12,now);gain.gain.exponentialRampToValueAtTime(.001,now+.18);osc.connect(gain);osc.start();osc.stop(now+.2);osc.onended=()=>{osc.disconnect();gain.disconnect();};}}
