  function startGame(){for(const k in magazines)delete magazines[k];closeOverlay(false);clearInput();zombies.forEach(disposeEnemy);menuZombies.forEach(disposeEnemy);zombies=[];menuZombies=[];clearEffects();Tactical?.reset();state.mode='playing';state.wave=0;state.kills=0;state.earned=0;state.hp=maxHp();state.weapon=saved.equipped;state.ammo=weapons[state.weapon].mag;state.reload=0;state.shotCooldown=0;state.yaw=0;state.pitch=0;state.sinceHit=100;state.runTime=0;state.nextWave=0;state.recoil=0;state.blastShake=0;state.waveCleared=false;state.fromPause=false;hideTransient();camera.position.set(0,1.72,17);camera.rotation.set(0,0,0);camera.fov=68;camera.updateProjectionMatrix();W.buildGun(state.weapon);W.gun.visible=true;$('main-menu').classList.add('hidden');$('site-header').classList.add('hidden');$('game-hud').classList.remove('hidden');document.body.classList.add('playing');$('kill-feed').innerHTML='';if(sound){initAudio();audio?.resume?.().catch(()=>{});}requestLock();beginWave();hud();if(!storageAvailable)toast('この環境では保存が利用できません。進行は今回のプレイ中のみ保持されます。');}
