  function chooseTier(){if(state.wave>=5&&state.spawnLeft===1)return 4;if(state.wave>=4&&Math.random()<.15)return 3;if(state.wave>=3&&Math.random()<.23)return 2;if(state.wave>=2&&Math.random()<.36)return 1;return 0;}
  function addHealthBar(e){const g=new T.Group();e.root.add(g);g.position.y=2.35;const bg=new T.Sprite(new T.SpriteMaterial({color:0x162a25,depthTest:false}));bg.scale.set(.7,.055,1);g.add(bg);const fg=new T.Sprite(new T.SpriteMaterial({color:new T.Color(tiers[e.tier].hex),depthTest:false}));fg.scale.set(.7,.045,1);fg.center.set(0,.5);fg.position.set(-.35,0,.005);g.add(fg);e.healthBar=g;e.healthFill=fg;bg.userData.disposable=fg.userData.disposable=true;g.visible=false;}
  function spawnEnemy(){let x,z,best=null,bestScore=-Infinity;for(let tries=0;tries<25;tries++){const cx=W.rand(-7.5,7.5),direction=Math.random()<.78?-1:1,cz=T.MathUtils.clamp(camera.position.z+direction*W.rand(19,33),-80,33);if(W.blocked(cx,cz,.9))continue;const d=Math.hypot(cx-camera.position.x,cz-camera.position.z);if(d>=13){best=[cx,cz];break;}if(d>bestScore){bestScore=d;best=[cx,cz];}}if(!best)best=[0,camera.position.z>-50?-80:33];[x,z]=best;const e=W.createZombie(chooseTier(),x,z);if(state.wave>5){const scale=1+(state.wave-5)*.08;e.hp*=scale;e.maxHp=e.hp;e.damage*=1+(state.wave-5)*.045;}addHealthBar(e);zombies.push(e);state.spawnLeft--;hud();}
