  let returnMode='menu',previousFocus=null;
  function openModal(type){if(state.mode==='dead'&&type!=='death')return;if(state.mode==='playing'){returnMode='playing';state.mode='paused';clearInput();releaseLock();hideTransient();if(type!=='shop')setAudioActive(false);}else if(state.mode==='menu')returnMode='menu';if($('overlay').classList.contains('hidden'))previousFocus=document.activeElement;$('overlay').setAttribute('aria-hidden','false');state.lastModal=type;if(type==='shop')setAudioActive(true);$('overlay').classList.remove('hidden');$('modal').style.maxWidth=type==='pause'||type==='death'?'550px':'';renderModal(type);$('modal-close').focus();}
